INSERT INTO "records" VALUES('artwork','NFA-0001',1,'{"title": "The Quiet Stalls", "caption": "Horses rest where honeysuckle has found the timber. Morning arrives slowly here, and nobody hurries it.", "edition": 1, "price": "£29.00", "price_pence": 2900, "currency": "GBP", "image": "/nft-art/art/nfa-0001.webp", "thumb": "/nft-art/art/nfa-0001-t.webp", "alt": "Horses resting in a stable wreathed in honeysuckle and roses, painted in gold light", "src": "/wayback/images/facebook/0000-00-00_1414847607339495_848558048327086.jpg", "src_sha16": "df7e0a861a33345a", "source_id": "FB-848558048327086", "source_title": "a farm photograph in the Wayback Vault (FB-848558048327086)", "master_px": "768x960", "master_sha256": "9a256d9317254d86e213762ca99e4fef9d5f6e4f42e3bd120d9f4e48ba0eb6b1", "buy": "https://buy.stripe.com/aFa3cwe8j3Q3cGE10b6Zy0n", "issued": "2026-10-27"}');
